scripts.script:
import java.nio.file.*

def srcDir = new File(project.build.directory, 'generated-sources/fixes')

def patches = [
  // Make invoke() public so KaModCommandFix can call it directly without reflection
  [file: 'org/jetbrains/kotlin/idea/codeinsight/api/applicable/intentions/KotlinPsiUpdateModCommandAction.kt',
   old:  'protected abstract fun invoke(',
   new_: 'public abstract fun invoke('],
]

// Remove ClassBased and Contextless inner classes from KotlinPsiUpdateModCommandAction —
// we only use ElementBased. ClassBased imports ContextProvider/getElementContext/KtElement
// which are not in our classpath; Contextless also uses KtElement.
def modCommandFile = new File(srcDir,
  'org/jetbrains/kotlin/idea/codeinsight/api/applicable/intentions/KotlinPsiUpdateModCommandAction.kt')
if (modCommandFile.exists()) {
  def lines = modCommandFile.readLines()
  def out = []
  def skipImports = [
    'import org.jetbrains.kotlin.idea.codeinsight.api.applicable.ContextProvider',
    'import org.jetbrains.kotlin.idea.codeinsight.api.applicable.getElementContext',
    'import org.jetbrains.kotlin.psi.KtElement',
    // Note: kotlin.reflect.KClass is kept — used in the sealed class constructor signature
  ]
  def skipClassMarkers = ['abstract class ClassBased', 'abstract class Contextless']
  def inSkippedClass = false
  def braceDepth = 0
  lines.each { line ->
    if (skipImports.any { line.startsWith(it) }) return
    if (!inSkippedClass && skipClassMarkers.any { line.contains(it) }) {
      inSkippedClass = true
      braceDepth = 0
    }
    if (inSkippedClass) {
      braceDepth += line.count('{') - line.count('}')
      if (braceDepth <= 0 && line.contains('}')) { inSkippedClass = false }
      return
    }
    out << line
  }
  modCommandFile.text = out.join('\n')
  log.info("Removed ClassBased and Contextless from KotlinPsiUpdateModCommandAction.kt")
}

patches.each { p ->
  def f = new File(srcDir, p.file)
  if (!f.exists()) { log.warn("patch target not found: ${p.file}"); return }
  def text = f.text
  if (!text.contains(p.old)) { log.warn("patch target not found in ${p.file}: '${p.old}'"); return }
  f.text = text.replace(p.old, p.new_)
  log.info("Patched ${p.file}")
}

// AddAccessorUtils: replace 'startOffset' extension (not on classpath) with 'textRange.startOffset'
def addAccessorUtilsFile = new File(srcDir,
  'org/jetbrains/kotlin/idea/codeinsights/impl/base/intentions/AddAccessorUtils.kt')
if (addAccessorUtilsFile.exists()) {
  def text = addAccessorUtilsFile.text
  text = text.replace('import org.jetbrains.kotlin.psi.psiUtil.startOffset\n', '')
  text = text.replace('.startOffset', '.textRange.startOffset')
  addAccessorUtilsFile.text = text
  log.info("Patched AddAccessorUtils.kt: removed startOffset import, use textRange.startOffset")
}

// AddJvmInlineAnnotationFix: replace 'addAnnotation(ClassId)' (from base/code-insight, not on classpath)
// with direct KtPsiFactory annotation entry creation. Era 253 uses StandardKotlinNames.Jvm.JvmInline.
def addJvmInlineFile = new File(srcDir, 'org/jetbrains/kotlin/idea/quickfix/AddJvmInlineAnnotationFix.kt')
if (addJvmInlineFile.exists()) {
  def text = addJvmInlineFile.text
  text = text.replace('import org.jetbrains.kotlin.idea.util.addAnnotation\n', '')
  text = text.replace('import org.jetbrains.kotlin.name.ClassId\n', '')
  text = text.replace('import org.jetbrains.kotlin.idea.codeinsight.utils.StandardKotlinNames\n', '')
  // Era 222 body (kept for safety — no-op on era 253)
  text = text.replace('import org.jetbrains.kotlin.name.FqName\n', '')
  text = text.replace(
    '''        val jvmInlineFqName = FqName("kotlin.jvm.JvmInline")
        val jvmInlineClassId = ClassId.topLevel(jvmInlineFqName)
        element.addAnnotation(jvmInlineClassId)''',
    '''        element.addAnnotationEntry(KtPsiFactory(actionContext.project).createAnnotationEntry("@kotlin.jvm.JvmInline"))'''
  )
  // Era 253 body
  text = text.replace(
    '''        val jvmInlineClassId = ClassId.topLevel(StandardKotlinNames.Jvm.JvmInline)
        element.addAnnotation(jvmInlineClassId)''',
    '''        element.addAnnotationEntry(KtPsiFactory(actionContext.project).createAnnotationEntry("@kotlin.jvm.JvmInline"))'''
  )
  // add KtPsiFactory import if not already present
  if (!text.contains('import org.jetbrains.kotlin.psi.KtPsiFactory')) {
    text = text.replace('import org.jetbrains.kotlin.psi.KtClass\n',
                        'import org.jetbrains.kotlin.psi.KtClass\nimport org.jetbrains.kotlin.psi.KtPsiFactory\n')
  }
  addJvmInlineFile.text = text
  log.info("Patched AddJvmInlineAnnotationFix.kt: replaced addAnnotation(ClassId) with KtPsiFactory")
}

// AddReturnExpressionFix: remove safeAs and endOffset (not on classpath); simplify invoke body.
def addReturnExprFile = new File(srcDir, 'org/jetbrains/kotlin/idea/quickfix/AddReturnExpressionFix.kt')
if (addReturnExprFile.exists()) {
  def text = addReturnExprFile.text
  text = text.replace('import org.jetbrains.kotlin.psi.psiUtil.endOffset\n', '')
  text = text.replace('import org.jetbrains.kotlin.utils.addToStdlib.safeAs\n', '')
  text = text.replace('import org.jetbrains.kotlin.psi.KtReturnExpression\n', '')
  // Replace the body: remove safeAs cast, updater.select, updater.moveCaretTo
  text = text.replace(
    '''        val returnExpression = psiFactory.createExpression("return TODO(\\"${KotlinBundle.message("provide.return.value")}\\")")
        val todo = bodyBlock.addBefore(returnExpression, rBrace).safeAs<KtReturnExpression>()?.returnedExpression ?: return
        updater.select(todo)
        updater.moveCaretTo(todo.endOffset)''',
    '''        val returnExpression = psiFactory.createExpression("return TODO(\\"Provide return value\\")")
        bodyBlock.addBefore(returnExpression, rBrace)'''
  )
  addReturnExprFile.text = text
  log.info("Patched AddReturnExpressionFix.kt: removed safeAs/endOffset, simplified invoke body")
}
